// VAT Report Tests
import { vatSummary } from '../src/reports.js';

test('vatSummary returns empty array for empty invoices', () => {
  const r = vatSummary([]);
  assert.deepEqual(r, []);
});

test('vatSummary returns empty array for null invoices', () => {
  const r = vatSummary(null);
  assert.deepEqual(r, []);
});

test('vatSummary excludes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });

  const r = vatSummary([draft.value]);
  assert.deepEqual(r, []);
});

test('vatSummary with single issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);

  // DES-HOUR: 8500 cents, 21% VAT
  // base = 8500, vat = 1785
  const r = vatSummary([issued.value]);
  assert.equal(r.length, 1);
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 8500);
  assert.equal(r[0].vat, 1785);
});

test('vatSummary includes partially_paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const partial = recordPayment(issued.value, { amount: 5000, date: '2026-10-10' });

  const r = vatSummary([partial.value]);
  assert.equal(r.length, 1);
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 8500);
  assert.equal(r[0].vat, 1785);
});

test('vatSummary includes paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const paid = recordPayment(issued.value, { amount: 10285, date: '2026-10-10' });

  const r = vatSummary([paid.value]);
  assert.equal(r.length, 1);
  assert.equal(r[0].rate, 21);
});

test('vatSummary with multiple lines of same VAT rate', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
    ],
  });
  const issued = issueInvoice(invoice.value, []);

  // Two DES-HOUR lines: (8500 + 8500) = 17000 base, (1785 + 1785) = 3570 vat
  const r = vatSummary([issued.value]);
  assert.equal(r.length, 1);
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 17000);
  assert.equal(r[0].vat, 3570);
});

test('vatSummary with multiple different VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 }, // 21% VAT
      { sku: 'DES-CONSUMABLE', qty: 1, discountPercent: 0 }, // 9% VAT
    ],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = vatSummary([issued.value]);
  assert.equal(r.length, 2);
  // Sorted by rate descending (21 first, then 9)
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 8500);
  assert.equal(r[0].vat, 1785);
  assert.equal(r[1].rate, 9);
  assert.equal(r[1].base, 2500);
  assert.equal(r[1].vat, 225);
});

test('vatSummary calculates base after discount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);

  // DES-HOUR: 8500, 10% discount = 850 discount
  // base = 8500 - 850 = 7650
  // vat = 7650 * 0.21 = 1606.50 -> 1607 (rounded)
  const r = vatSummary([issued.value]);
  assert.equal(r[0].base, 7650);
  assert.equal(r[0].vat, 1607);
});

test('vatSummary with zero VAT rate', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 }, // 21% VAT
      { sku: 'TRAINING', qty: 1, discountPercent: 0 }, // 0% VAT
    ],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = vatSummary([issued.value]);
  assert.equal(r.length, 2);
  assert.equal(r[0].rate, 21);
  assert.equal(r[1].rate, 0);
  assert.equal(r[1].base, 10000);
  assert.equal(r[1].vat, 0);
});

test('vatSummary aggregates across multiple invoices', () => {
  const invoice1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const r = vatSummary([issued1.value, issued2.value]);
  assert.equal(r.length, 1);
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 17000); // 8500 + 8500
  assert.equal(r[0].vat, 3570); // 1785 + 1785
});

test('vatSummary sorts by rate descending', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'TRAINING', qty: 1, discountPercent: 0 }, // 0% VAT
      { sku: 'DES-CONSUMABLE', qty: 1, discountPercent: 0 }, // 9% VAT
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 }, // 21% VAT
    ],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = vatSummary([issued.value]);
  assert.equal(r.length, 3);
  assert.equal(r[0].rate, 21);
  assert.equal(r[1].rate, 9);
  assert.equal(r[2].rate, 0);
});

test('vatSummary includes correct fields', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = vatSummary([issued.value]);
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 8500);
  assert.equal(r[0].vat, 1785);
  assert.equal(Object.keys(r[0]).length, 3); // exactly 3 fields
});

test('vatSummary with multiple invoices and multiple rates', () => {
  const invoice1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 }, // 21%
      { sku: 'DES-CONSUMABLE', qty: 1, discountPercent: 0 }, // 9%
    ],
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-08',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 }, // 21%
      { sku: 'TRAINING', qty: 1, discountPercent: 0 }, // 0%
    ],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const r = vatSummary([issued1.value, issued2.value]);
  assert.equal(r.length, 3);
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 17000); // 8500 + 8500
  assert.equal(r[0].vat, 3570); // 1785 + 1785
  assert.equal(r[1].rate, 9);
  assert.equal(r[1].base, 2500);
  assert.equal(r[1].vat, 225);
  assert.equal(r[2].rate, 0);
  assert.equal(r[2].base, 10000);
  assert.equal(r[2].vat, 0);
});

