    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
    ],
  });
  const issued = issueInvoice(invoice.value, []);

  // Two DES-HOUR lines: (8500 + 8500) = 17000 base, (1785 + 1785) = 3570 vat
  const r = vatSummary([issued.value]);
  assert.equal(r.length, 1);
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 17000);
  assert.equal(r[0].vat, 3570);
});

test('vatSummary with multiple different VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 1, discountPercent: 0 }, // 9% VAT
    ],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = vatSummary([issued.value]);
  assert.equal(r.length, 2);
  // Sorted by rate descending (21 first, then 9)
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 8500);
  assert.equal(r[0].vat, 1785);
  assert.equal(r[1].rate, 9);
  assert.equal(r[1].base, 37);
  assert.equal(r[1].vat, 3); // 37 * 0.09 = 3.33 -> 3
});

test('vatSummary calculates base after discount', () => {
